/* ===================== BÀI 37 · LED bảy đoạn và bảng mã ===================== */
/* Bài 37 · LED bảy đoạn và bảng mã (AMTS-EMB-001-M10-L01, MC51-037) — sinh bởi tools/author/mcu8051/l37.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8051 và bài tập chấm tự động (đề, code mẫu, bộ thử). Lời giải không nằm ở đây. */
const PR37=[{"label":"Ví dụ: Hiện số 5 trên LED anode chung","code":"; Ví dụ 1: hiện số 5 trên một LED 7 đoạn anode chung\n; AT89S52, 12 MHz. Đoạn a…g, dp nối P0.0…P0.7 (giả định\n; của trình mô phỏng); anode chung nên đoạn sáng khi chân = 0.\n        ORG     0000H\n        MOV     P0,#92H                 ; 1001 0010B: a c d f g sáng = số 5\n        SJMP    $\n        END\n","note":"Một lệnh MOV P0,#92H (75 80 92, 2 chu kỳ) bật năm đoạn a, c, d, f, g: các bit bằng 0 trong 92H = 1001 0010B (bit 0, 2, 3, 5, 6) ứng với đoạn sáng. Đổi thành #0C0H rồi chạy lại để thấy số 0.","dev":{"seg":{"sel":[],"digits":1}},"fosc":12000000,"speed":"fast"},{"label":"Ví dụ: Tra bảng mã bằng MOVC A,@A+DPTR","code":"; Ví dụ 2: tra bảng mã trong bộ nhớ CODE bằng MOVC\n; Chữ số ở ô 30H, mã anode chung ra P0.\n        ORG     0000H\n        MOV     30H,#7                  ; chữ số cần hiện\n        MOV     A,30H                   ; A = chỉ số trong bảng\n        MOV     DPTR,#SEGCA             ; DPTR = địa chỉ đầu bảng\n        MOVC    A,@A+DPTR               ; A = byte ở CODE[DPTR + A]\n        MOV     P0,A                    ; xuất mẫu đoạn\n        SJMP    $\n; mã anode chung (bit = 0: đoạn sáng) của số 0…9\nSEGCA:  DB      0C0H,0F9H,0A4H,0B0H,99H,92H,82H,0F8H,80H,90H\n        END\n","note":"Theo dõi lệnh MOVC: A = 07H, DPTR = 000DH nên CPU đọc CODE[0014H] = F8H (phần tử thứ 8 của bảng, đếm từ 0). Tổng 8 chu kỳ tới SJMP $; bảng bắt đầu ở 000DH, ngay sau 2 byte của SJMP $.","dev":{"seg":{"sel":[],"digits":1}},"fosc":12000000,"speed":"fast"},{"label":"Bẫy: Bảng anode chung trên LED cathode chung","code":"; Ví dụ 3 (bẫy): bảng anode chung gắn với LED cathode chung\n; Trình mô phỏng ở ví dụ này nối LED cathode chung:\n; đoạn sáng khi chân = 1. Chương trình muốn hiện số 1.\n        ORG     0000H\n        MOV     30H,#1                  ; chữ số cần hiện\n        MOV     A,30H\n        MOV     DPTR,#SEGCA\n        MOVC    A,@A+DPTR               ; A = 0F9H (mã anode chung của 1)\n        MOV     P0,A                    ; cathode chung: bit 1 mới sáng\n        SJMP    $\nSEGCA:  DB      0C0H,0F9H,0A4H,0B0H,99H,92H,82H,0F8H,80H,90H\n        END\n","note":"Ví dụ này nối LED cathode chung (sáng khi bit = 1) nhưng dùng bảng anode chung. Muốn hiện số 1, chương trình xuất F9H = 1111 1001B: các đoạn a, d, e, f, g và dp sáng, thành hình giống “E.” — đúng phần bù của số 1.","dev":{"seg":{"sel":[],"digits":1,"activeLow":false}},"fosc":12000000,"speed":"fast"},{"label":"Ví dụ: Đếm 0 đến 9, mỗi số khoảng 80 ms","code":"; Ví dụ 4: đếm 0…9, mỗi số giữ khoảng 80 ms\n; Chạy ở tốc độ Thời gian thực để thấy số đổi.\n        ORG     0000H\n        MOV     DPTR,#SEGCA             ; bảng mã\n        MOV     R2,#0                   ; chữ số đang hiện\nNEXT:   MOV     A,R2\n        MOVC    A,@A+DPTR               ; tra mã\n        MOV     P0,A                    ; hiện số\n        ACALL   D80MS                   ; giữ khoảng 80 ms\n        INC     R2\n        CJNE    R2,#10,NEXT             ; đủ 10 số chưa?\n        MOV     P0,#0FFH                ; tắt mọi đoạn\n        SJMP    $\n; trễ 1 + 160 x 499 + 2 = 79 843 chu kỳ máy\nD80MS:  MOV     R6,#160\nDL1:    MOV     R7,#248\n        DJNZ    R7,$                    ; 248 x 2 chu kỳ\n        DJNZ    R6,DL1\n        RET\nSEGCA:  DB      0C0H,0F9H,0A4H,0B0H,99H,92H,82H,0F8H,80H,90H\n        END\n","note":"Đặt sẵn tốc độ Thời gian thực: số chạy 0 → 9, mỗi số khoảng 80 ms (79 852 chu kỳ máy mỗi vòng). Tổng 798 525 chu kỳ ≈ 0,80 s ở 12 MHz rồi tắt LED. Đổi sang Từ từ để thấy từng lệnh của vòng trễ.","dev":{"seg":{"sel":[],"digits":1}},"fosc":12000000,"speed":"real"},{"label":"Bẫy: Chữ số 10 đọc ra ngoài bảng","code":"; Ví dụ 5 (bẫy): chữ số 10 đọc ra ngoài bảng\n; Ngay sau bảng số là bảng chọn chữ số của bài sau.\n        ORG     0000H\n        MOV     30H,#10                 ; dữ liệu sai: không phải 0…9\n        MOV     A,30H\n        MOV     DPTR,#SEGCA\n        MOVC    A,@A+DPTR               ; đọc CODE[SEGCA + 10]\n        MOV     P0,A\n        SJMP    $\nSEGCA:  DB      0C0H,0F9H,0A4H,0B0H,99H,92H,82H,0F8H,80H,90H\nSELTAB: DB      0FEH,0FDH,0FBH,0F7H\n        END\n","note":"Chữ số 10 vượt bảng 10 phần tử: MOVC đọc byte đầu của bảng SELTAB nằm ngay sau (FEH = 1111 1110B). Với anode chung chỉ bit 0 bằng 0 nên chỉ đoạn a sáng (một gạch trên cùng) — không phải số nào và cũng không có báo lỗi.","dev":{"seg":{"sel":[],"digits":1}},"fosc":12000000,"speed":"fast"},{"label":"Ví dụ: Kiểm tra giới hạn trước khi tra bảng","code":"; Ví dụ 6: kiểm tra giới hạn trước khi tra bảng\n; Chữ số > 9 thì hiện dấu '-' (chỉ đoạn g sáng).\n        ORG     0000H\n        MOV     30H,#12                 ; thử với dữ liệu sai\n        MOV     DPTR,#SEGCA\n        MOV     A,30H\n        CJNE    A,#10,CHK               ; CY = 1 nếu A < 10\nCHK:    JC      OK\n        MOV     P0,#0BFH                ; '-' : chỉ đoạn g (P0.6) = 0\n        SJMP    DONE\nOK:     MOVC    A,@A+DPTR\n        MOV     P0,A\nDONE:   SJMP    $\nSEGCA:  DB      0C0H,0F9H,0A4H,0B0H,99H,92H,82H,0F8H,80H,90H\n        END\n","note":"CJNE A,#10,CHK nhảy tới ngay lệnh sau (CHK) nhưng đặt CY = 1 nếu A < 10. Với 12, CY = 0 nên chương trình hiện “-” (BFH: chỉ đoạn g sáng). Đổi 30H thành 4 để thấy nhánh tra bảng.","dev":{"seg":{"sel":[],"digits":1}},"fosc":12000000,"speed":"fast"}];
const sim37=makeSim51(document.getElementById("m51-l37"),{id:"s37",presets:PR37,ram:256});
makeEx51(document.getElementById("ex-l37"),"l37",[{"t":"Bảng mã cathode chung tự soạn","d":"<p>Một bo thứ hai dùng LED 7 đoạn <b>cathode chung<\/b> qua IC đệm: đoạn a, b, c, d, e, f, g, dp nối P2.0 … P2.7, đoạn sáng khi chân = <b>1<\/b>. Ô <code>30H<\/code> chứa một chữ số 0–9. Tự soạn bảng mã 10 byte <code>SEGCC<\/code> trong bộ nhớ CODE (code mẫu mới có mã số 0), tra bảng để xuất mã của chữ số ra <code>P2<\/code> và chép mã đó vào ô <code>31H<\/code>. Ô <code>30H<\/code> giữ nguyên. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: <code>30H = 05H<\/code> → <code>P2 = 6DH<\/code>, <code>31H = 6DH<\/code>.<\/p>","start":"        ORG     0000H\n; Viết code ở đây: tra bảng SEGCC theo chữ số ở 30H,\n; xuất mã ra P2 và chép mã vào 31H.\n        SJMP    $\n; Viết tiếp mã cathode chung của số 1…9 sau mã số 0\nSEGCC:  DB      3FH\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":5,"0x31":238}},"expect":{"ports":{"P2":109},"iram":{"0x30":5,"0x31":109}}},{"setup":{"iram":{"0x30":0,"0x31":238}},"expect":{"ports":{"P2":63},"iram":{"0x30":0,"0x31":63}}},{"setup":{"iram":{"0x30":9,"0x31":238}},"expect":{"ports":{"P2":111},"iram":{"0x30":9,"0x31":111}}},{"setup":{"iram":{"0x30":1,"0x31":238}},"expect":{"ports":{"P2":6},"iram":{"0x30":1,"0x31":6}}},{"setup":{"iram":{"0x30":8,"0x31":238}},"expect":{"ports":{"P2":127},"iram":{"0x30":8,"0x31":127}}},{"setup":{"iram":{"0x30":7,"0x31":238}},"expect":{"ports":{"P2":7},"iram":{"0x30":7,"0x31":7}}}]},"hints":["Liệt kê đoạn sáng của từng số (hình 37.1), đặt bit 1 cho đoạn sáng theo a = bit 0 … g = bit 6. Cathode chung sáng ở mức 1 nên KHÔNG đảo byte. Số 0: a b c d e f → 0011 1111B = 3FH.","Bảng nằm sau SJMP $ để CPU không chạy nhầm vào dữ liệu. Nạp DPTR = SEGCA, A = chữ số, rồi MOVC A,@A+DPTR.","Kiểm lại: mã cathode chung là phần bù của mã anode chung trong bảng ở mục 37.2, ví dụ 1 → 06H (anode chung F9H), 8 → 7FH (80H)."],"why":"Bảng tra là cách nhanh và rõ nhất để đổi chữ số sang mẫu đoạn: một lệnh MOVC (2 chu kỳ) thay cho chuỗi so sánh. Mã phụ thuộc vào cả cực tính (cathode chung: 1 = sáng, không đảo) và cách nối chân, nên phải tự lập bảng cho đúng bo. Bộ thử số 1 bắt lỗi chép nhầm bảng anode chung (F9H thay vì 06H)."},{"t":"Bảng mã cho bo nối ngược chân","d":"<p>Một bo khác nối LED anode chung theo thứ tự ngược: a → P0.7, b → P0.6, c → P0.5, d → P0.4, e → P0.3, f → P0.2, g → P0.1, dp → P0.0 (đoạn sáng khi chân = 0). Ô <code>30H<\/code> chứa mẫu đoạn viết theo <b>bo chuẩn<\/b> của khóa: bit 0 = a … bit 6 = g, bit 7 = dp, bit 1 = đoạn sáng (mã cathode chung). Viết chương trình đổi mẫu này thành giá trị đúng cho bo mới, xuất ra <code>P0<\/code> và chép vào ô <code>31H<\/code>; ô <code>30H<\/code> giữ nguyên. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: số 5 có <code>30H = 6DH<\/code> (0110 1101B) → đảo thứ tự bit được 1011 0110B = B6H → anode chung đảo mức được <code>P0 = 49H<\/code>, <code>31H = 49H<\/code>.<\/p>","start":"        ORG     0000H\n        MOV     A,30H                   ; mẫu chuẩn: bit 0 = a … bit 7 = dp\n        CPL     A                       ; anode chung: đảo mức\n        MOV     P0,A                    ; (còn thiếu: đổi thứ tự chân)\n        MOV     31H,A\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":109,"0x31":238}},"expect":{"ports":{"P0":73},"iram":{"0x30":109,"0x31":73}}},{"setup":{"iram":{"0x30":63,"0x31":238}},"expect":{"ports":{"P0":3},"iram":{"0x30":63,"0x31":3}}},{"setup":{"iram":{"0x30":6,"0x31":238}},"expect":{"ports":{"P0":159},"iram":{"0x30":6,"0x31":159}}},{"setup":{"iram":{"0x30":128,"0x31":238}},"expect":{"ports":{"P0":254},"iram":{"0x30":128,"0x31":254}}},{"setup":{"iram":{"0x30":0,"0x31":238}},"expect":{"ports":{"P0":255},"iram":{"0x30":0,"0x31":255}}},{"setup":{"iram":{"0x30":1,"0x31":238}},"expect":{"ports":{"P0":127},"iram":{"0x30":1,"0x31":127}}}]},"hints":["Hai việc: đổi thứ tự 8 bit (bit 0 ↔ bit 7, bit 1 ↔ bit 6 …) rồi đảo mức (CPL A). Code mẫu mới làm việc thứ hai.","Đổi thứ tự bit bằng vòng lặp 8 lần qua cờ CY: RRC A lấy bit thấp nhất của nguồn ra CY, RLC trên một thanh ghi đích đẩy CY vào bit thấp của đích.","Hai thanh ghi luân phiên làm nguồn và đích; một lệnh đổi chỗ A với thanh ghi kia giúp dùng RRC/RLC cho cả hai."],"why":"Bảng mã gắn với cách nối dây: cùng số 5 nhưng bo khác cần byte khác. Khi đổi bo, có thể soạn lại bảng hoặc đổi mẫu bằng phần mềm như bài này (đổi thứ tự bit rồi đảo mức). Bộ thử “chỉ đoạn a” bắt lỗi quên đổi thứ tự: 01H phải thành 7FH, không phải FEH."},{"t":"Hai chữ số hex trong ≤ 16 chu kỳ","d":"<p>Ô <code>30H<\/code> chứa một byte. Ghi mã anode chung của chữ số hex <b>nửa cao<\/b> vào ô <code>31H<\/code> và của <b>nửa thấp<\/b> vào ô <code>32H<\/code> (bảng <code>HEXCA<\/code> 16 byte cho 0–F đã có trong code mẫu, chữ A b C d E F). Ô <code>30H<\/code> giữ nguyên. Code mẫu cho kết quả đúng nhưng chạy 18 chu kỳ máy và dài 39 byte. Hãy tối ưu để toàn chương trình chạy <b>không quá 16 chu kỳ máy<\/b> (tính cả một lần <code>SJMP $<\/code>) và dài <b>không quá 36 byte<\/b> (tính cả bảng).<\/p><p>Ví dụ: <code>30H = 3CH<\/code> → <code>31H = B0H<\/code> (số 3), <code>32H = C6H<\/code> (chữ C).<\/p>","start":"        ORG     0000H\n        MOV     DPTR,#HEXCA\n        MOV     A,30H\n        ANL     A,#0FH                  ; nửa thấp\n        MOVC    A,@A+DPTR\n        MOV     32H,A\n        MOV     A,30H\n        RR      A                       ; đưa nửa cao xuống\n        RR      A\n        RR      A\n        RR      A\n        ANL     A,#0FH\n        MOVC    A,@A+DPTR\n        MOV     31H,A\n        SJMP    $\nHEXCA:  DB      0C0H,0F9H,0A4H,0B0H,99H,92H,82H,0F8H\n        DB      80H,90H,88H,83H,0C6H,0A1H,86H,8EH\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":60,"0x31":238,"0x32":238}},"expect":{"iram":{"0x30":60,"0x31":176,"0x32":198}}},{"setup":{"iram":{"0x30":0,"0x31":238,"0x32":238}},"expect":{"iram":{"0x30":0,"0x31":192,"0x32":192}}},{"setup":{"iram":{"0x30":255,"0x31":238,"0x32":238}},"expect":{"iram":{"0x30":255,"0x31":142,"0x32":142}}},{"setup":{"iram":{"0x30":165,"0x31":238,"0x32":238}},"expect":{"iram":{"0x30":165,"0x31":136,"0x32":146}}},{"setup":{"iram":{"0x30":158,"0x31":238,"0x32":238}},"expect":{"iram":{"0x30":158,"0x31":144,"0x32":134}}},{"setup":{"iram":{"0x30":18,"0x31":238,"0x32":238}},"expect":{"iram":{"0x30":18,"0x31":249,"0x32":164}}}],"maxCyc":16,"maxBytes":36},"hints":["Chạy code mẫu từng bước: bốn lệnh RR A tốn 4 byte và 4 chu kỳ chỉ để đưa nửa cao xuống nửa thấp.","Có một lệnh 1 byte, 1 chu kỳ đổi chỗ hai nửa của A.","Lời giải mẫu: 20 byte mã + 16 byte bảng = 36 byte, 15 chu kỳ máy."],"why":"Lệnh SWAP đổi hai nửa 4 bit của thanh ghi A trong 1 chu kỳ, thay cho bốn lệnh RR A: bớt 3 byte và 3 chu kỳ. Với chương trình hiển thị chạy hàng trăm lần mỗi giây (bài sau), vài chu kỳ mỗi lần cộng lại thành phần đáng kể thời gian CPU."}]);

makeQuiz("quiz37","score37",[{"q": "LED 7 đoạn anode chung nối a…g, dp vào P0.0…P0.7. Byte nào hiện số 7 (đoạn a, b, c)?", "o": ["07H", "E0H", "1FH", "F8H"], "a": 3, "e": "Đoạn a, b, c là bit 0, 1, 2 → mã cathode chung 0000 0111B = 07H. Anode chung sáng ở mức 0 nên đảo: 1111 1000B = F8H. 07H là mã cho LED cathode chung; E0H là đảo nhưng sai thứ tự bit."}, {"q": "Bảng 10 byte SEGCA đặt ngay sau SJMP $, ngay sau bảng là bảng SELTAB. Chạy MOV A,#10 · MOV DPTR,#SEGCA · MOVC A,@A+DPTR thì sao?", "o": ["A nhận byte đầu của SELTAB; không có lỗi nào được báo", "CPU dừng và báo lỗi vượt bảng", "A nhận lại byte cuối của SEGCA", "A = 0 vì không có phần tử thứ 10"], "a": 0, "e": "MOVC chỉ cộng địa chỉ, không biết bảng dài bao nhiêu. Địa chỉ SEGCA + 10 là byte đầu của bảng kế tiếp. Phải kiểm tra chỉ số trước khi tra."}, {"q": "Lệnh MOVC A,@A+PC nằm ở 0007H, sau nó là MOV P0,A (2 byte) và SJMP $ (2 byte), rồi tới bảng. Cần cộng bao nhiêu vào chỉ số trước khi tra?", "o": ["5", "4", "7", "0"], "a": 1, "e": "Khi MOVC chạy, PC đã là 0008H (lệnh kế tiếp). Bảng ở 0008H + 4 = 000CH, nên A = chỉ số + 4. Cộng 5 là quên rằng PC đã tăng qua chính lệnh MOVC."}, {"q": "Tính điện trở hạn dòng cho một đoạn với giả định V_CC = 5 V, V_F = 2,0 V, V_OL = 0,45 V, I_F = 10 mA. Giá trị nào hợp lý?", "o": ["500 Ω, chọn 510 Ω", "300 Ω, chọn 330 Ω", "255 Ω, chọn 270 Ω", "45 Ω, chọn 47 Ω"], "a": 2, "e": "R = (5 − 2,0 − 0,45) V / 0,010 A = 255 Ω; chọn giá trị chuẩn lớn hơn gần nhất 270 Ω để dòng không vượt 10 mA. 500 Ω là quên trừ V_F và V_OL; 300 Ω là quên trừ V_OL."}, {"q": "Vì sao mỗi đoạn cần một điện trở riêng thay vì một điện trở chung ở chân anode?", "o": ["Để vi điều khiển đọc được trạng thái từng đoạn", "Vì điện trở chung làm LED cathode chung không sáng", "Với điện trở chung, các đoạn chia nhau dòng nên độ sáng đổi theo số đoạn đang sáng", "Vì P0 chỉ chịu được một điện trở"], "a": 2, "e": "Dòng qua một điện trở chung được chia cho mọi đoạn đang sáng: số 1 (2 đoạn) sáng hơn số 8 (7 đoạn), và LED có V_F lệch nhau sáng không đều."}]);

fillSnips();
